// /ai/research-story already returns plot (converted scene bullets via
// the server-side storyToDescription() port, WS1.2), socialTitle, and
// socialCaption — no markdown parsing needed here anymore (that used to
// happen in this node; it's now server-side, shared with the wizard's
// Show Bible / manual-prompt paths).
const resp = $json;
if (!resp.plot) throw new Error('ai/research-story returned no plot — ' + (resp.message || 'unknown error'));
return [{ json: { plot: resp.plot, socialTitle: resp.socialTitle || '', socialCaption: resp.socialCaption || '' } }];

// Shape the engine call: episode mode in the wizard-configured campaign, the story
// as the new episode's plot, optional soundtrack pin. The engine's sub-workflow
// trigger is passthrough — this item IS the payload (same shape as the engine
// webhook's body). Re-delivered same-day stories are diff-aware on the engine
// side, so a duplicate run doesn't re-bill unchanged work.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty');
const movie = { plot: $json.plot };
if (cfg.soundtrackAudioPath) {
  movie.soundtrackAudioPath = cfg.soundtrackAudioPath;
  if (cfg.soundtrackVolume) movie.soundtrackVolume = Number(cfg.soundtrackVolume);
}
return [{ json: { target: { mode: 'episode', campaignId: cfg.campaignId }, changes: { movie }, apiBase: cfg.apiBase || '', userId: cfg.userId || '', chatWebhookUrl: '' } }];

// When postToSocial is true, publishes to every network linked to the
// campaign — one /social/post-movie call per campaign link.
// The gate lives in Show config (postToSocial); set it false for review-first
// runs. Zero items out (gate off, or no networks linked) = the posting node
// simply doesn't fire, and the run stays green.
const cfg = $('Show config').first().json;
if (!cfg.postToSocial) return [];
const resp = $('Fetch campaign links').first().json || {};
if (!Array.isArray(resp.campaignLinks)) throw new Error('could not list campaign links for social posting (' + (resp.error?.message || 'no campaignLinks in response') + ') — check the "YakYak API" credential has the social_publishing scope, or set Show config postToSocial=false');
const movieId = $('Call engine').first().json.movieId;
return resp.campaignLinks.filter((r) => r.connectedNetworkId).map((r) => ({ json: { movieId, connectedNetworkId: r.connectedNetworkId, socialNetworkName: r.socialNetworkName || '' } }));
